<template>
  <section><div class="page-heading"><div><p class="eyebrow">المصروفات</p><h1>المصروفات التشغيلية</h1></div><button class="primary" @click="add">تسجيل مصروف</button></div><div class="panel"><table><thead><tr><th>الوصف</th><th>التصنيف</th><th>المبلغ</th><th>التاريخ</th></tr></thead><tbody><tr v-for="e in expenses" :key="e._id"><td>{{ e.description }}</td><td>{{ e.category }}</td><td>{{ money(e.amount) }}</td><td>{{ e.date }}</td></tr></tbody></table><p v-if="!expenses.length" class="empty">لم تسجل مصروفات</p></div></section>
</template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import db from '../services/pouchdb';const expenses=ref<any[]>([]);const money=(v:number)=>new Intl.NumberFormat('ar-YE',{style:'currency',currency:'YER',maximumFractionDigits:0}).format(v);async function load(){expenses.value=await db.list<any>('expense')}async function add(){const description=prompt('وصف المصروف');if(!description)return;const amount=Number(prompt('المبلغ')||0);if(!amount)return;await db.put({_id:`expense:${Date.now()}`,type:'expense',description,category:prompt('التصنيف')||'عام',amount,date:new Date().toISOString().slice(0,10)});await load()}onMounted(load)</script>
